public enum TicketPrioridad {
    BAJA(48, "🟢"),
    MEDIA(24, "🟡"),
    ALTA(8, "🟠"),
    CRITICA(2, "🔴");

    private final int tiempoRespuesta;
    private final String emoji;

    TicketPrioridad(int tiempoRespuesta, String emoji) {
        this.tiempoRespuesta = tiempoRespuesta;
        this.emoji = emoji;
    }

    public int getTiempoRespuesta() { return tiempoRespuesta; }
    public String getEmoji() { return emoji; }

    public boolean esUrgente() {
        return this == ALTA || this == CRITICA;
    }
}

public class SistemaTickets {
    public static void main(String[] args) {
        for (TicketPrioridad p : TicketPrioridad.values()) {
            System.out.printf("Prioridad %s: ⏱ %sh %s - ¿Urgente? %s%n",
                p.name(), p.getTiempoRespuesta(),
                p.getEmoji(), p.esUrgente());
        }
    }
}

