public enum PlanSuscripcion {
    GRATIS(0, 0.5, 1),
    BASICO(9.99, 10, 5),
    PREMIUM(29.99, 100, 50),
    EMPRESARIAL(99.99, 1000, 999);

    private final double precioMensual;
    private final double almacenamientoGB;
    private final int maxUsuarios;

    PlanSuscripcion(double precioMensual, double almacenamientoGB, int maxUsuarios) {
        this.precioMensual = precioMensual;
        this.almacenamientoGB = almacenamientoGB;
        this.maxUsuarios = maxUsuarios;
    }

    public double getPrecioMensual() { return precioMensual; }
    public double getAlmacenamientoGB() { return almacenamientoGB; }
    public int getMaxUsuarios() { return maxUsuarios; }
    public boolean esGratuito() { return precioMensual == 0; }

    public double precioAnual() {
        return precioMensual * 12 * 0.9;  // 10% de descuento anual
    }

    public boolean soportaAlmacenamiento(double gb) {
        return almacenamientoGB >= gb;
    }
}

public class CalculadoraPlanes {
    public static void main(String[] args) {
        // Mostrar todos los planes
        System.out.println("=== Planes de suscripción ===\n");

        for (PlanSuscripcion plan : PlanSuscripcion.values()) {
            System.out.printf("%s: $%.2f/mes → $%.2f/año | %.0fGB | %d usuarios",
                plan.name(), plan.getPrecioMensual(),
                plan.precioAnual(),
                plan.getAlmacenamientoGB(),
                plan.getMaxUsuarios());

            if (plan.esGratuito()) {
                System.out.print(" (GRATIS)");
            }
            System.out.println();
        }

        // Verificar soporte de almacenamiento
        System.out.println("\n=== Soporte de 50GB ===");
        for (PlanSuscripcion plan : PlanSuscripcion.values()) {
            System.out.printf("%s: %s%n", plan.name(),
                plan.soportaAlmacenamiento(50) ? "✅" : "❌");
        }

        // Recomendación
        System.out.println("\n=== Recomendación para startup de 20 usuarios ===");
        for (PlanSuscripcion plan : PlanSuscripcion.values()) {
            if (plan.getMaxUsuarios() >= 20 && !plan.esGratuito()) {
                System.out.printf("→ %s: $%.2f/mes (%d usuarios, %.0fGB)%n",
                    plan.name(), plan.getPrecioMensual(),
                    plan.getMaxUsuarios(), plan.getAlmacenamientoGB());
                break;
            }
        }
    }
}
